INSERT INTO sentences (id, language_id, text, reading_kana, level_id, source, published) VALUES
INSERT INTO sentence_translations (id, sentence_id, lang, text, source) VALUES
  ('st-ex-nashiniwa-1', 'sent-ex-nashiniwa-1', 'en', 'Without effort there can be no success.', 'authored'),
  ('st-ex-nashiniwa-2', 'sent-ex-nashiniwa-2', 'en', 'Without his help it could not have been done.', 'authored'),
  ('st-ex-nashiniwa-3', 'sent-ex-nashiniwa-3', 'en', 'It cannot be started without preparation.', 'authored'),
  ('st-ex-nashiniwa-4', 'sent-ex-nashiniwa-4', 'en', 'It cannot be explained without the material.', 'authored'),
  ('st-ex-taritomo-1', 'sent-ex-taritomo-1', 'en', 'I do not forget it for a single day.', 'authored'),
  ('st-ex-taritomo-2', 'sent-ex-taritomo-2', 'en', 'I will not let a single one of them off.', 'authored'),
  ('st-ex-taritomo-3', 'sent-ex-taritomo-3', 'en', 'I have not been late even once.', 'authored'),
  ('st-ex-taritomo-4', 'sent-ex-taritomo-4', 'en', 'I cannot afford to miss a single word.', 'authored'),
  ('st-ex-toiedomo-1', 'sent-ex-toiedomo-1', 'en', 'Child though he is, he has responsibilities.', 'authored'),
  ('st-ex-toiedomo-2', 'sent-ex-toiedomo-2', 'en', 'Even a doctor makes mistakes.', 'authored'),
  ('st-ex-toiedomo-3', 'sent-ex-toiedomo-3', 'en', 'Busy though I am, I need a day off.', 'authored'),
  ('st-ex-toiedomo-4', 'sent-ex-toiedomo-4', 'en', 'Even the company president must not break the rules.', 'authored'),
  ('st-ex-towa-1', 'sent-ex-towa-1', 'en', 'I never thought he would come.', 'authored'),
  ('st-ex-towa-2', 'sent-ex-towa-2', 'en', 'I was astonished that he should fail.', 'authored'),
  ('st-ex-towa-3', 'sent-ex-towa-3', 'en', 'I had no idea it was that simple.', 'authored'),
  ('st-ex-towa-4', 'sent-ex-towa-4', 'en', 'I had no idea he was the company president.', 'authored'),
  ('st-ex-monowo-1', 'sent-ex-monowo-1', 'en', 'If only you had said so sooner.', 'authored'),
  ('st-ex-monowo-2', 'sent-ex-monowo-2', 'en', 'If you had asked, I would have helped.', 'authored'),
  ('st-ex-monowo-3', 'sent-ex-monowo-3', 'en', 'You should have rested, and instead you worked on.', 'authored'),
  ('st-ex-monowo-4', 'sent-ex-monowo-4', 'en', 'If you had apologised, I would have forgiven you.', 'authored'),
  ('st-ex-beku-1', 'sent-ex-beku-1', 'en', 'I am working hard in order to succeed.', 'authored'),
  ('st-ex-beku-2', 'sent-ex-beku-2', 'en', 'I studied in order to pass the exam.', 'authored'),
  ('st-ex-beku-3', 'sent-ex-beku-3', 'en', 'I ran in order to get there quickly.', 'authored'),
  ('st-ex-beku-4', 'sent-ex-beku-4', 'en', 'We talked in order to solve the problem.', 'authored'),
  ('st-ex-bekarazu-1', 'sent-ex-bekarazu-1', 'en', 'Do not enter.', 'authored'),
  ('st-ex-bekarazu-2', 'sent-ex-bekarazu-2', 'en', 'No photography.', 'authored'),
  ('st-ex-bekarazu-3', 'sent-ex-bekarazu-3', 'en', 'A promise is not to be forgotten.', 'authored'),
  ('st-ex-bekarazu-4', 'sent-ex-bekarazu-4', 'en', 'No swimming in the river.', 'authored'),
  ('st-ex-nagarani-1', 'sent-ex-nagarani-1', 'en', 'He spoke in tears.', 'authored'),
  ('st-ex-nagarani-2', 'sent-ex-nagarani-2', 'en', 'It is a natural-born talent.', 'authored'),
  ('st-ex-nagarani-3', 'sent-ex-nagarani-3', 'en', 'We make it by the old method.', 'authored'),
  ('st-ex-nagarani-4', 'sent-ex-nagarani-4', 'en', 'She apologised in tears.', 'authored'),
  ('st-ex-yainaya-1', 'sent-ex-yainaya-1', 'en', 'No sooner had I got home than it rained.', 'authored'),
  ('st-ex-yainaya-2', 'sent-ex-yainaya-2', 'en', 'The moment he heard, he ran off.', 'authored'),
  ('st-ex-yainaya-3', 'sent-ex-yainaya-3', 'en', 'The moment I entered the shop, I spotted him.', 'authored'),
  ('st-ex-yainaya-4', 'sent-ex-yainaya-4', 'en', 'The moment I sat down, I fell asleep.', 'authored'),
  ('st-ex-gahayaika-1', 'sent-ex-gahayaika-1', 'en', 'The instant the bell rang, he was out of the classroom.', 'authored'),
  ('st-ex-gahayaika-2', 'sent-ex-gahayaika-2', 'en', 'He ate and was out of the door in the same breath.', 'authored'),
  ('st-ex-gahayaika-3', 'sent-ex-gahayaika-3', 'en', 'He hung up and went straight out.', 'authored'),
  ('st-ex-gahayaika-4', 'sent-ex-gahayaika-4', 'en', 'The moment he heard, he broke into a run.', 'authored')
