-- N1 example sentences, batch 1: the literary register opens.
--
-- N1 is where the grammar stops sounding like speech. なしには, たりとも,
-- といえども, とは, ものを, べく, べからず and ながらに belong to notices,
-- speeches and written argument; や否や and が早いか are the two ways to say
-- one thing happened the instant another did, and they are written back to
-- back so the difference — や否や is neutral, が早いか is abrupt — has
-- somewhere to show.
--
-- Nothing had to be reworded, which was not expected at this level.
--
-- One authoring note for the next batch: 〜ものを ends in the particle を, so
-- its spoken reading is 「もの お」 and not 「ものを」. The tokeniser accepts
-- either and only the first is what a learner would say.
--
-- Additive, idempotent, safe on a live database.

  -- nashi-ni-wa
  ('sent-ex-nashiniwa-1', 'lang-ja', '努力なしには成功できない。', 'どりょく なし に わ せいこう できない。', 'lvl-ja-n1', 'authored', true),
  ('sent-ex-nashiniwa-2', 'lang-ja', '彼の協力なしにはできなかった。', 'かれ の きょうりょく なし に わ できなかった。', 'lvl-ja-n1', 'authored', true),
  ('sent-ex-nashiniwa-3', 'lang-ja', '準備なしには始められません。', 'じゅんび なし に わ はじめられません。', 'lvl-ja-n1', 'authored', true),
  ('sent-ex-nashiniwa-4', 'lang-ja', '資料なしには説明できない。', 'しりょう なし に わ せつめい できない。', 'lvl-ja-n1', 'authored', true),
  -- taritomo
  ('sent-ex-taritomo-1', 'lang-ja', '一日たりとも忘れない。', 'いちにち たりとも わすれない。', 'lvl-ja-n1', 'authored', true),
  ('sent-ex-taritomo-2', 'lang-ja', '一人たりとも許さない。', 'ひとり たりとも ゆるさない。', 'lvl-ja-n1', 'authored', true),
  ('sent-ex-taritomo-3', 'lang-ja', '一度たりとも遅れたことがない。', 'いちど たりとも おくれた こと が ない。', 'lvl-ja-n1', 'authored', true),
  ('sent-ex-taritomo-4', 'lang-ja', '一言たりとも聞き逃せない。', 'ひとこと たりとも ききのがせない。', 'lvl-ja-n1', 'authored', true),
  -- to-iedomo
  ('sent-ex-toiedomo-1', 'lang-ja', '子供といえども、責任はある。', 'こども と いえども、せきにん わ ある。', 'lvl-ja-n1', 'authored', true),
  ('sent-ex-toiedomo-2', 'lang-ja', '医者といえども、間違いはある。', 'いしゃ と いえども、まちがい わ ある。', 'lvl-ja-n1', 'authored', true),
  ('sent-ex-toiedomo-3', 'lang-ja', '忙しいといえども、休みは必要だ。', 'いそがしい と いえども、やすみ わ ひつよう だ。', 'lvl-ja-n1', 'authored', true),
  ('sent-ex-toiedomo-4', 'lang-ja', '社長といえども、規則を破ってはならない。', 'しゃちょう と いえども、きそく お やぶって わ ならない。', 'lvl-ja-n1', 'authored', true),
  -- towa
  ('sent-ex-towa-1', 'lang-ja', '彼が来るとは思わなかった。', 'かれ が くる と わ おもわなかった。', 'lvl-ja-n1', 'authored', true),
  ('sent-ex-towa-2', 'lang-ja', '彼が失敗するとは驚いた。', 'かれ が しっぱい する と わ おどろいた。', 'lvl-ja-n1', 'authored', true),
  ('sent-ex-towa-3', 'lang-ja', 'そんなに簡単だとは知らなかった。', 'そんなに かんたん だ と わ しらなかった。', 'lvl-ja-n1', 'authored', true),
  ('sent-ex-towa-4', 'lang-ja', '彼が社長だとは知らなかった。', 'かれ が しゃちょう だ と わ しらなかった。', 'lvl-ja-n1', 'authored', true),
  -- mono-wo
  ('sent-ex-monowo-1', 'lang-ja', '早く言えばよかったものを。', 'はやく いえば よかった もの お。', 'lvl-ja-n1', 'authored', true),
  ('sent-ex-monowo-2', 'lang-ja', '相談すれば助けたものを。', 'そうだん すれば たすけた もの お。', 'lvl-ja-n1', 'authored', true),
  ('sent-ex-monowo-3', 'lang-ja', '休めばよかったものを、働き続けた。', 'やすめば よかった もの お、はたらきつづけた。', 'lvl-ja-n1', 'authored', true),
  ('sent-ex-monowo-4', 'lang-ja', '謝れば許したものを。', 'あやまれば ゆるした もの お。', 'lvl-ja-n1', 'authored', true),
  -- beku
  ('sent-ex-beku-1', 'lang-ja', '成功すべく努力しています。', 'せいこう すべく どりょく して います。', 'lvl-ja-n1', 'authored', true),
  ('sent-ex-beku-2', 'lang-ja', '試験に合格すべく勉強した。', 'しけん に ごうかく すべく べんきょう した。', 'lvl-ja-n1', 'authored', true),
  ('sent-ex-beku-3', 'lang-ja', '早く着くべく走った。', 'はやく つくべく はしった。', 'lvl-ja-n1', 'authored', true),
  ('sent-ex-beku-4', 'lang-ja', '問題を解決すべく話し合った。', 'もんだい お かいけつ すべく はなしあった。', 'lvl-ja-n1', 'authored', true),
  -- bekarazu
  ('sent-ex-bekarazu-1', 'lang-ja', '中に入るべからず。', 'なか に はいるべからず。', 'lvl-ja-n1', 'authored', true),
  ('sent-ex-bekarazu-2', 'lang-ja', '写真を撮るべからず。', 'しゃしん お とるべからず。', 'lvl-ja-n1', 'authored', true),
  ('sent-ex-bekarazu-3', 'lang-ja', '約束を忘れるべからず。', 'やくそく お わすれるべからず。', 'lvl-ja-n1', 'authored', true),
  ('sent-ex-bekarazu-4', 'lang-ja', '川で泳ぐべからず。', 'かわ で およぐべからず。', 'lvl-ja-n1', 'authored', true),
  -- nagara-ni
  ('sent-ex-nagarani-1', 'lang-ja', '彼は涙ながらに話した。', 'かれ わ なみだ ながら に はなした。', 'lvl-ja-n1', 'authored', true),
  ('sent-ex-nagarani-2', 'lang-ja', '生まれながらの才能だ。', 'うまれ ながら の さいのう だ。', 'lvl-ja-n1', 'authored', true),
  ('sent-ex-nagarani-3', 'lang-ja', '昔ながらの方法で作ります。', 'むかし ながら の ほうほう で つくります。', 'lvl-ja-n1', 'authored', true),
  ('sent-ex-nagarani-4', 'lang-ja', '彼女は涙ながらに謝った。', 'かのじょ わ なみだ ながら に あやまった。', 'lvl-ja-n1', 'authored', true),
  -- ya-ina-ya
  ('sent-ex-yainaya-1', 'lang-ja', '家に着くや否や、雨が降った。', 'いえ に つく や いな や、あめ が ふった。', 'lvl-ja-n1', 'authored', true),
  ('sent-ex-yainaya-2', 'lang-ja', '話を聞くや否や、走って行った。', 'はなし お きく や いな や、はしって いった。', 'lvl-ja-n1', 'authored', true),
  ('sent-ex-yainaya-3', 'lang-ja', '店に入るや否や、彼を見つけた。', 'みせ に はいる や いな や、かれ お みつけた。', 'lvl-ja-n1', 'authored', true),
  ('sent-ex-yainaya-4', 'lang-ja', '座るや否や、寝てしまいました。', 'すわる や いな や、ねて しまいました。', 'lvl-ja-n1', 'authored', true),
  -- ga-hayai-ka
  ('sent-ex-gahayaika-1', 'lang-ja', 'ベルが鳴るが早いか、教室を出た。', 'ベル が なる が はやい か、きょうしつ お でた。', 'lvl-ja-n1', 'authored', true),
  ('sent-ex-gahayaika-2', 'lang-ja', '彼は食べるが早いか、出て行った。', 'かれ わ たべる が はやい か、でて いった。', 'lvl-ja-n1', 'authored', true),
  ('sent-ex-gahayaika-3', 'lang-ja', '電話を切るが早いか、出かけた。', 'でんわ お きる が はやい か、でかけた。', 'lvl-ja-n1', 'authored', true),
  ('sent-ex-gahayaika-4', 'lang-ja', '話を聞くが早いか、走り出しました。', 'はなし お きく が はやい か、はしりだしました。', 'lvl-ja-n1', 'authored', true)
ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO NOTHING;

